impl Solution{pub fn maximal_rectangle(m:Vec<Vec<char>>)->i32{fn hist(h:&[i32])->i32{let mut st:Vec<usize>=vec![];let mut b=0;for i in 0..=h.len(){let cur=if i==h.len(){0}else{h[i]};while let Some(&j)=st.last(){if h[j]<=cur{break}let ht=h[st.pop().unwrap()];let l=st.last().map(|&x|x as i32).unwrap_or(-1);b=b.max(ht*(i as i32-l-1));}st.push(i);}b}if m.is_empty(){return 0}let mut h=vec![0;m[0].len()];let mut b=0;for r in m{for j in 0..r.len(){h[j]=if r[j]=='1'{h[j]+1}else{0};}b=b.max(hist(&h));}b}}
